def run(c,root,args):
 c.group='library-fileio';pub=root/'labs/foundations/library_depth';private=root/'assessor/legacy_library';foundation=root/'assessor/foundations/foundation.c';include=root/'labs/foundations/include';source=private/'fileio.c'
 for cc in ('gcc','clang'):
  for name,flags in [('debug',['-O0']),('release',['-O2']),('sanitize',['-O1','-fsanitize=address,undefined','-fno-pie','-no-pie'])]:
   for mode,test in [('fileio',pub/'fileio_tests.c'),('fileio-host',private/'fileio_host.c')]:
    exe=c.root/(cc+'-'+name+'-'+mode);c.run([cc,'-std=c17','-Wall','-Wextra','-Werror',*flags,'-I'+str(pub),'-I'+str(include),test,source,foundation,'-o',exe]);c.run([exe],contains='FILEIO-PASS:')
    if mode=='fileio-host':c.run([exe,'borrow'],contains='borrowed-alive')
 for name,flag,selected in [('fileio-replay','LI_MUTANT_REPLAY',source),('fileio-error','LI_MUTANT_ERROR',source),('fileio-close','LI_MUTANT_CLOSE',source),('fileio-learner','UNSOLVED',pub/'fileio.c')]:
  exe=c.root/name;c.run(['gcc','-std=c17','-O2','-D'+flag,'-I'+str(pub),'-I'+str(include),pub/'fileio_tests.c',selected,foundation,'-o',exe]);c.run([exe],expected=1,contains='FILEIO-CHECK:')
 c.require('f_write_all(' in source.read_text(),'actual accepted prefix writer imported; zero remains terminal under that contract')
 for key,ordinary,changed in [('11.a','Owned FILE buffers outlive close; actual orientation/EOF traces copy ab,c,EOF into abc; one close consumes ownership','Borrowed stdout is flushed and remains usable for subsequent output; borrowed input neither flushed nor closed by release'),('11.b','Original scripted32 copy histories and actual GNU-cookie errors separate read/short-write/close failure and preserve committed prefixes; ISO update transitions are exercised','Actual owned nonseekable pipes force EAGAIN and resume retained suffix without seeking/replay; terminal output failures report exact committed prefix and forbid restart-as-rollback'),('11.c','Inspected POSIX active-handle contract governs synchronized FILE/descriptor switching; forbidden unsynchronized access remains analysis-only','Two FILE objects over one duplicated open-file description alternate with explicit input synchronization and repositioning; observed d/e sequence follows declared shared-offset ownership')]:c.observe('T12.'+key,ordinary,['library-fileio']);c.observe('T12.'+key,changed,['library-fileio'],True)
